1	package codec
2	
3	import (
4		"bufio"
5		"bytes"
6		"encoding/binary"
7		"errors"
8		"fmt"
9		"io"
10		"sort"
11		"sync"
12		"testing"
13	)
14	
15	// chunkReader returns its data in fixed-size chunks, simulating a byte
16	// stream whose block boundaries are unrelated to frame boundaries.
17	type chunkReader struct {
18		data []byte
19		n    int // bytes returned so far
20		size int // chunk size
21	}
22	
23	func (c *chunkReader) Read(p []byte) (int, error) {
24		if c.n >= len(c.data) {
25			return 0, io.EOF
26		}
27		end := c.n + c.size
28		if end > len(c.data) {
29			end = len(c.data)
30		}
31		n := copy(p, c.data[c.n:end])
32		c.n += n
33		return n, nil
34	}
35	
36	func encodeFrames(t *testing.T, fs []Frame) []byte {
37		t.Helper()
38		var buf bytes.Buffer
39		for _, f := range fs {
40			b, err := Encode(f)
41			if err != nil {
42				t.Fatalf("Encode: %v", err)
43			}
44			buf.Write(b)
45		}
46		return buf.Bytes()
47	}
48	
49	func framesEqual(a, b Frame) bool {
50		// Encode always writes Version regardless of the input field, so a
51		// decoded frame carries Version; compare b's other fields only.
52		return a.Version == Version && a.Flags == b.Flags && a.Kind == b.Kind && bytes.Equal(a.Payload, b.Payload)
53	}
54	
55	func drain(t *testing.T, s *Session) ([]Frame, error) {
56		t.Helper()
57		var got []Frame
58		for {
59			f, err := s.ReadFrame()
60			if err != nil {
61				return got, err
62			}
63			got = append(got, f)
64		}
65	}
66	
67	func TestSessionRoundTripChunks(t *testing.T) {
68		in := []Frame{
69			{Flags: 1, Kind: 2, Payload: nil},
70			{Flags: 3, Kind: 4, Payload: []byte("hello, frame")},
71			{Flags: 0xBEEF, Kind: 0x2A, Payload: bytes.Repeat([]byte{'x'}, 5000)},
72			{Flags: 99, Kind: 7, Payload: []byte{}},
73		}
74		wire := encodeFrames(t, in)
75	
76		// Every chunk size from 1 byte up to the full stream length must
77		// yield the same frame sequence: frame boundaries may land exactly
78		// on read-block boundaries, a block may contain several full frames
79		// plus a half frame, and the stream may start with empty input.
80		for _, size := range []int{1, 2, 3, 7, 10, 11, 13, 64, 4096, len(wire)} {
81			t.Run(fmt.Sprintf("chunk=%d", size), func(t *testing.T) {
82				s := NewSession(io.Discard, &chunkReader{data: wire, size: size})
83				got, err := drain(t, s)
84				if !errors.Is(err, io.EOF) {
85					t.Fatalf("terminal err = %v, want io.EOF", err)
86				}
87				if len(got) != len(in) {
88					t.Fatalf("got %d frames, want %d", len(got), len(in))
89				}
90				for i := range in {
91					if !framesEqual(got[i], in[i]) {
92						t.Fatalf("frame %d mismatch: got %+v want %+v", i, got[i], in[i])
93					}
94				}
95			})
96		}
97	}
98	
99	func TestSessionEmptyInput(t *testing.T) {
100		s := NewSession(io.Discard, &chunkReader{data: nil, size: 4})
101		if _, err := s.ReadFrame(); !errors.Is(err, io.EOF) {
102			t.Fatalf("err = %v, want io.EOF on empty input", err)
103		}
104		// After a clean end, reads keep returning io.EOF without a new error.
105		if _, err := s.ReadFrame(); !errors.Is(err, io.EOF) {
106			t.Fatalf("second err = %v, want io.EOF", err)
107		}
108	}
109	
110	func TestSessionWriteOrderingAndFlush(t *testing.T) {
111		var out bytes.Buffer
112		s := NewSession(&out, nil)
113	
114		in := []Frame{
115			{Flags: 1, Kind: 1, Payload: []byte("first")},
116			{Flags: 2, Kind: 2, Payload: []byte("second")},
117			{Flags: 3, Kind: 3, Payload: []byte("third")},
118		}
119		for _, f := range in {
120			if err := s.WriteFrame(f); err != nil {
121				t.Fatalf("WriteFrame: %v", err)
122			}
123		}
124		// Nothing reaches the writer before flush.
125		if out.Len() != 0 {
126			t.Fatalf("%d bytes written before Flush", out.Len())
127		}
128		if err := s.Flush(); err != nil {
129			t.Fatalf("Flush: %v", err)
130		}
131		if !bytes.Equal(out.Bytes(), encodeFrames(t, in)) {
132			t.Fatalf("flushed bytes differ from concatenated single frames")
133		}
134	
135		// Buffer reuse: frames appended after a flush must not carry bytes
136		// from the previous run.
137		more := []Frame{{Flags: 4, Kind: 4, Payload: []byte("after")}}
138		for _, f := range more {
139			if err := s.WriteFrame(f); err != nil {
140				t.Fatalf("WriteFrame: %v", err)
141			}
142		}
143		if err := s.Flush(); err != nil {
144			t.Fatalf("Flush: %v", err)
145		}
146		got, err := drain(t, NewSession(nil, bytes.NewReader(out.Bytes())))
147		if err != io.EOF && !errors.Is(err, io.EOF) {
148			t.Fatalf("drain: %v", err)
149		}
150		want := append(in, more...)
151		if len(got) != len(want) {
152			t.Fatalf("got %d frames, want %d", len(got), len(want))
153		}
154		for i := range want {
155			if !framesEqual(got[i], want[i]) {
156				t.Fatalf("frame %d = %+v, want %+v", i, got[i], want[i])
157			}
158		}
159	}
160	
161	func TestSessionFlushPropagatesToBufferedWriter(t *testing.T) {
162		var raw bytes.Buffer
163		bw := bufio.NewWriter(&raw)
164		s := NewSession(bw, nil)
165		f := Frame{Payload: []byte("buffered")}
166		if err := s.WriteFrame(f); err != nil {
167			t.Fatalf("WriteFrame: %v", err)
168		}
169		if err := s.Flush(); err != nil {
170			t.Fatalf("Flush: %v", err)
171		}
172		if raw.Len() == 0 {
173			t.Fatal("Flush did not flush the underlying *bufio.Writer")
174		}
175	}
176	
177	func TestSessionFlushRetriesAfterShortWrite(t *testing.T) {
178		fw := &faultyWriter{limit: 3, fail: errFaultyWrite}
179		s := NewSession(fw, nil)
180		in := []Frame{
181			{Kind: 1, Payload: []byte("first-frame")},
182			{Kind: 2, Payload: []byte("second-frame")},
183		}
184		for _, f := range in {
185			if err := s.WriteFrame(f); err != nil {
186				t.Fatalf("WriteFrame: %v", err)
187			}
188		}
189		if err := s.Flush(); !errors.Is(err, errFaultyWrite) {
190			t.Fatalf("Flush err = %v, want errFaultyWrite", err)
191		}
192	
193		// The unsent tail must survive; once the writer recovers the next
194		// Flush completes the ordered stream with no gap or duplication.
195		fw.limit = 1 << 20
196		fw.fail = nil
197		if err := s.Flush(); err != nil {
198			t.Fatalf("retry Flush: %v", err)
199		}
200		got, err := drain(t, NewSession(nil, bytes.NewReader(fw.buf.Bytes())))
201		if !errors.Is(err, io.EOF) {
202			t.Fatalf("drain: %v", err)
203		}
204		if len(got) != len(in) {
205			t.Fatalf("got %d frames, want %d", len(got), len(in))
206		}
207		for i := range in {
208			if !framesEqual(got[i], in[i]) {
209				t.Fatalf("frame %d = %+v, want %+v", i, got[i], in[i])
210			}
211		}
212	}
213	
214	func TestSessionWriteTooLarge(t *testing.T) {
215		var out bytes.Buffer
216		s := NewSession(&out, nil)
217	
218		good := Frame{Kind: 1, Payload: []byte("ok")}
219		if err := s.WriteFrame(good); err != nil {
220			t.Fatalf("WriteFrame good: %v", err)
221		}
222		// Oversized payload is rejected before any of its bytes are buffered.
223		if err := s.WriteFrame(Frame{Kind: 2, Payload: make([]byte, MaxPayload+1)}); !errors.Is(err, ErrTooLarge) {
224			t.Fatalf("err = %v, want ErrTooLarge", err)
225		}
226		if err := s.WriteFrame(good); err != nil {
227			t.Fatalf("WriteFrame good after reject: %v", err)
228		}
229		if err := s.Flush(); err != nil {
230			t.Fatalf("Flush: %v", err)
231		}
232	
233		got, err := drain(t, NewSession(nil, bytes.NewReader(out.Bytes())))
234		if !errors.Is(err, io.EOF) {
235			t.Fatalf("drain: %v", err)
236		}
237		if len(got) != 2 {
238			t.Fatalf("got %d frames, want 2 (rejected frame left no half frame)", len(got))
239		}
240		for _, g := range got {
241			if !framesEqual(g, good) {
242				t.Fatalf("got %+v, want the two accepted frames", g)
243			}
244		}
245	}
246	
247	func TestSessionIncrementalArrival(t *testing.T) {
248		// Feed a half frame, then the rest plus a full frame, then close:
249		// the residual must wait without error and be completed by later
250		// bytes.
251		f1 := Frame{Kind: 1, Payload: []byte("abcdef")}
252		f2 := Frame{Kind: 2, Payload: []byte("gh")}
253		w1, err := Encode(f1)
254		if err != nil {
255			t.Fatal(err)
256		}
257		w2, err := Encode(f2)
258		if err != nil {
259			t.Fatal(err)
260		}
261		wire := append(append([]byte(nil), w1...), w2...)
262	
263		r := &blockingFeed{}
264		s := NewSession(io.Discard, r)
265	
266		got := make(chan Frame, 2)
267		errc := make(chan error, 2)
268		go func() {
269			for {
270				f, err := s.ReadFrame()
271				if err != nil {
272					errc <- err
273					return
274				}
275				got <- f
276			}
277		}()
278	
279		// Half of frame 1: no frame, no error yet.
280		r.append(wire[:HeaderSize+2])
281		r.append(wire[HeaderSize+2:]) // rest of frame 1 + all of frame 2
282		r.closeFeed()
283	
284		first := <-got
285		second := <-got
286		if !framesEqual(first, f1) || !framesEqual(second, f2) {
287			t.Fatalf("frames = %+v, %+v", first, second)
288		}
289		if err := <-errc; !errors.Is(err, io.EOF) {
290			t.Fatalf("terminal err = %v, want io.EOF", err)
291		}
292	}
293	
294	func TestSessionTruncatedTailAtEOF(t *testing.T) {
295		good := Frame{Kind: 1, Payload: []byte("complete")}
296		w, err := Encode(good)
297		if err != nil {
298			t.Fatal(err)
299		}
300		// A complete frame followed by a half frame of the next one.
301		half := w[:HeaderSize+1]
302		stream := append(append([]byte(nil), w...), half...)
303	
304		s := NewSession(io.Discard, bytes.NewReader(stream))
305		f, err := s.ReadFrame()
306		if err != nil {
307			t.Fatalf("first frame: %v", err)
308		}
309		if !framesEqual(f, good) {
310			t.Fatalf("first frame = %+v", f)
311		}
312		_, err = s.ReadFrame()
313		if !errors.Is(err, ErrShortFrame) {
314			t.Fatalf("truncated tail err = %v, want ErrShortFrame", err)
315		}
316		// The half frame is not delivered as a frame; the short-frame error
317		// is sticky on subsequent reads.
318		_, err = s.ReadFrame()
319		if !errors.Is(err, ErrShortFrame) {
320			t.Fatalf("second err = %v, want sticky ErrShortFrame", err)
321		}
322	}
323	
324	func TestSessionBadFrameStopsWithPriorFrames(t *testing.T) {
325		good1 := Frame{Kind: 1, Payload: []byte("one")}
326		good2 := Frame{Kind: 2, Payload: []byte("two")}
327		good3 := Frame{Kind: 3, Payload: []byte("three")}
328		w1, _ := Encode(good1)
329		w2, _ := Encode(good2)
330		bad, _ := Encode(Frame{Kind: 9, Payload: []byte("bad")})
331		bad[HeaderSize] ^= 0xFF // payload corruption -> checksum mismatch
332		w3, _ := Encode(good3)
333		stream := append(append(append(append([]byte(nil), w1...), w2...), bad...), w3...)
334	
335		s := NewSession(io.Discard, bytes.NewReader(stream))
336		f1, err := s.ReadFrame()
337		if err != nil || !framesEqual(f1, good1) {
338			t.Fatalf("frame 1 = %+v, %v", f1, err)
339		}
340		f2, err := s.ReadFrame()
341		if err != nil || !framesEqual(f2, good2) {
342			t.Fatalf("frame 2 = %+v, %v", f2, err)
343		}
344		_, err = s.ReadFrame()
345		if !errors.Is(err, ErrChecksum) {
346			t.Fatalf("bad frame err = %v, want ErrChecksum", err)
347		}
348		// Frames after the corrupt one are not delivered; the error sticks.
349		_, err = s.ReadFrame()
350		if !errors.Is(err, ErrChecksum) {
351			t.Fatalf("follow-up err = %v, want sticky ErrChecksum", err)
352		}
353	}
354	
355	func TestSessionBadVersionAndTooLarge(t *testing.T) {
356		// Bad version mid-stream.
357		bad, _ := Encode(Frame{Payload: []byte("x")})
358		bad[4] = 2
359		s := NewSession(io.Discard, bytes.NewReader(bad))
360		if _, err := s.ReadFrame(); !errors.Is(err, ErrBadVersion) {
361			t.Fatalf("bad version err = %v, want ErrBadVersion", err)
362		}
363	
364		// Declared length over the limit, full frame present: the streaming
365		// side returns the same ErrTooLarge Decode returns.
366		payload := make([]byte, MaxPayload+1)
367		big := make([]byte, HeaderSize+len(payload))
368		binary.BigEndian.PutUint32(big[0:4], uint32(len(payload)))
369		big[4] = Version
370		sum := checksum(big[0:8]) + checksum(big[HeaderSize:])
371		binary.BigEndian.PutUint16(big[8:10], sum)
372	
373		// Deliver it in small chunks so the declared length is known long
374		// before the bytes arrive.
375		s = NewSession(io.Discard, &chunkReader{data: big, size: 4096})
376		if _, err := s.ReadFrame(); !errors.Is(err, ErrTooLarge) {
377			t.Fatalf("oversize err = %v, want ErrTooLarge", err)
378		}
379	}
380	
381	func TestSessionChecksumPrecedenceOverTooLarge(t *testing.T) {
382		// Mirrors TestDecodeErrorPrecedence on the streaming side: an
383		// oversize declared length with a broken checksum must surface
384		// ErrChecksum, even when delivered one byte at a time.
385		big := make([]byte, HeaderSize+MaxPayload+1)
386		binary.BigEndian.PutUint32(big[0:4], uint32(MaxPayload+1))
387		big[4] = Version
388		big[HeaderSize] = 1 // breaks the (zero) checksum
389		s := NewSession(io.Discard, &chunkReader{data: big, size: 1})
390		if _, err := s.ReadFrame(); !errors.Is(err, ErrChecksum) {
391			t.Fatalf("err = %v, want ErrChecksum", err)
392		}
393	}
394	
395	func TestSessionManyFramesUnbounded(t *testing.T) {
396		// Well past any fixed in-memory frame table: frame count is unbounded.
397		const n = 5000
398		var buf bytes.Buffer
399		s := NewSession(&buf, nil)
400		for i := 0; i < n; i++ {
401			if err := s.WriteFrame(Frame{Kind: uint8(i), Payload: []byte{byte(i), byte(i >> 8)}}); err != nil {
402				t.Fatalf("WriteFrame %d: %v", i, err)
403			}
404		}
405		if err := s.Flush(); err != nil {
406			t.Fatalf("Flush: %v", err)
407		}
408		r := NewSession(nil, &chunkReader{data: buf.Bytes(), size: 3})
409		for i := 0; i < n; i++ {
410			f, err := r.ReadFrame()
411			if err != nil {
412				t.Fatalf("frame %d: %v", i, err)
413			}
414			if f.Kind != uint8(i) || len(f.Payload) != 2 ||
415				f.Payload[0] != byte(i) || f.Payload[1] != byte(i>>8) {
416				t.Fatalf("frame %d = %+v", i, f)
417			}
418		}
419		if _, err := r.ReadFrame(); !errors.Is(err, io.EOF) {
420			t.Fatalf("terminal err = %v, want io.EOF", err)
421		}
422	}
423	
424	func TestSessionMaxPayloadAccepted(t *testing.T) {
425		var buf bytes.Buffer
426		s := NewSession(&buf, nil)
427		if err := s.WriteFrame(Frame{Payload: make([]byte, MaxPayload)}); err != nil {
428			t.Fatalf("MaxPayload frame rejected: %v", err)
429		}
430		if err := s.Flush(); err != nil {
431			t.Fatalf("Flush: %v", err)
432		}
433		f, err := NewSession(nil, bytes.NewReader(buf.Bytes())).ReadFrame()
434		if err != nil {
435			t.Fatalf("ReadFrame: %v", err)
436		}
437		if len(f.Payload) != MaxPayload {
438			t.Fatalf("payload len = %d, want %d", len(f.Payload), MaxPayload)
439		}
440	}
441	
442	func TestSessionConcurrentWritesNoInterleave(t *testing.T) {
443		var out lockedBuffer
444		s := NewSession(&out, nil)
445	
446		const writers = 16
447		const per = 200
448		var wg sync.WaitGroup
449		for g := 0; g < writers; g++ {
450			wg.Add(1)
451			go func(g int) {
452				defer wg.Done()
453				for i := 0; i < per; i++ {
454					payload := []byte(fmt.Sprintf("g%di%d", g, i))
455					if err := s.WriteFrame(Frame{Kind: uint8(g), Payload: payload}); err != nil {
456						t.Errorf("WriteFrame: %v", err)
457						return
458					}
459				}
460			}(g)
461		}
462		wg.Wait()
463		if err := s.Flush(); err != nil {
464			t.Fatalf("Flush: %v", err)
465		}
466	
467		// Every frame must decode cleanly whole: interleaved bytes would
468		// corrupt a header or checksum.
469		r := NewSession(nil, bytes.NewReader(out.bytes()))
470		counts := map[int]int{}
471		total := 0
472		for {
473			f, err := r.ReadFrame()
474			if errors.Is(err, io.EOF) {
475				break
476			}
477			if err != nil {
478				t.Fatalf("frame %d corrupted by interleaving: %v", total, err)
479			}
480			counts[int(f.Kind)]++
481			var gg, ii int
482			if _, err := fmt.Sscanf(string(f.Payload), "g%di%d", &gg, &ii); err != nil {
483				t.Fatalf("bad payload %q", f.Payload)
484			}
485			if gg != int(f.Kind) || ii < 0 || ii >= per {
486				t.Fatalf("payload/header mismatch: kind %d payload %q", f.Kind, f.Payload)
487			}
488			total++
489		}
490		if total != writers*per {
491			t.Fatalf("decoded %d frames, want %d", total, writers*per)
492		}
493		for g := 0; g < writers; g++ {
494			if counts[g] != per {
495				t.Fatalf("group %d produced %d frames, want %d", g, counts[g], per)
496			}
497		}
498	}
499	
500	func TestSessionConcurrentReadersEachFrameOnce(t *testing.T) {
501		const n = 2000
502		frames := make([]Frame, n)
503		for i := range frames {
504			frames[i] = Frame{Kind: uint8(i), Payload: []byte(fmt.Sprintf("%08d", i))}
505		}
506		wire := encodeFrames(t, frames)
507	
508		s := NewSession(io.Discard, bytes.NewReader(wire))
509		const readers = 8
510		var mu sync.Mutex
511		seen := make(map[string]int)
512		var wg sync.WaitGroup
513		for r := 0; r < readers; r++ {
514			wg.Add(1)
515			go func() {
516				defer wg.Done()
517				for {
518					f, err := s.ReadFrame()
519					if errors.Is(err, io.EOF) {
520						return
521					}
522					if err != nil {
523						t.Errorf("ReadFrame: %v", err)
524						return
525					}
526					key := string(f.Payload)
527					mu.Lock()
528					seen[key]++
529					mu.Unlock()
530				}
531			}()
532		}
533		wg.Wait()
534	
535		if len(seen) != n {
536			t.Fatalf("delivered %d distinct frames, want %d", len(seen), n)
537		}
538		ids := make([]int, 0, n)
539		for k, c := range seen {
540			if c != 1 {
541				t.Fatalf("frame %q delivered %d times", k, c)
542			}
543			var id int
544			fmt.Sscanf(k, "%08d", &id)
545			ids = append(ids, id)
546		}
547		sort.Ints(ids)
548		for i, id := range ids {
549			if id != i {
550				t.Fatalf("missing/duplicated frame at index %d (got %d)", i, id)
551			}
552		}
553	}
554	
555	func TestSessionConcurrentReadersAndWriters(t *testing.T) {
556		pr, pw := io.Pipe()
557		s := NewSession(pw, pr)
558	
559		const n = 500
560		var wg sync.WaitGroup
561		wg.Add(2)
562	
563		// Writer side: multiple goroutines append frames, one flusher pushes.
564		go func() {
565			defer wg.Done()
566			var fw sync.WaitGroup
567			for g := 0; g < 4; g++ {
568				fw.Add(1)
569				go func(g int) {
570					defer fw.Done()
571					for i := 0; i < n/4; i++ {
572						if err := s.WriteFrame(Frame{Kind: uint8(g), Payload: []byte(fmt.Sprintf("g%d-%d", g, i))}); err != nil {
573							t.Errorf("WriteFrame: %v", err)
574						}
575					}
576				}(g)
577			}
578			fw.Wait()
579			if err := s.Flush(); err != nil {
580				t.Errorf("Flush: %v", err)
581			}
582			pw.Close()
583		}()
584	
585		// Reader side: multiple goroutines share the read end.
586		got := make(chan Frame, n)
587		go func() {
588			defer wg.Done()
589			var fr sync.WaitGroup
590			for r := 0; r < 4; r++ {
591				fr.Add(1)
592				go func() {
593					defer fr.Done()
594					for {
595						f, err := s.ReadFrame()
596						if errors.Is(err, io.EOF) {
597							return
598						}
599						if err != nil {
600							t.Errorf("ReadFrame: %v", err)
601							return
602						}
603						got <- f
604					}
605				}()
606			}
607			fr.Wait()
608		}()
609		wg.Wait()
610		close(got)
611	
612		count := 0
613		for range got {
614			count++
615		}
616		if count != n {
617			t.Fatalf("got %d frames through concurrent session, want %d", count, n)
618		}
619	}
620	
621	func TestSessionReaderErrorSurfaces(t *testing.T) {
622		sentinel := errors.New("boom")
623		s := NewSession(io.Discard, &errReader{err: sentinel})
624		if _, err := s.ReadFrame(); !errors.Is(err, sentinel) {
625			t.Fatalf("err = %v, want underlying reader error", err)
626		}
627	}
628	
629	// --- helpers ---
630	
631	type lockedBuffer struct {
632		mu  sync.Mutex
633		buf bytes.Buffer
634	}
635	
636	func (b *lockedBuffer) Write(p []byte) (int, error) {
637		b.mu.Lock()
638		defer b.mu.Unlock()
639		return b.buf.Write(p)
640	}
641	
642	func (b *lockedBuffer) bytes() []byte {
643		b.mu.Lock()
644		defer b.mu.Unlock()
645		return b.buf.Bytes()
646	}
647	
648	type errReader struct{ err error }
649	
650	func (e *errReader) Read([]byte) (int, error) { return 0, e.err }
651	
652	var errFaultyWrite = errors.New("faulty write")
653	
654	// faultyWriter accepts at most limit bytes per Write and reports fail
655	// alongside them, simulating a short write at the transport.
656	type faultyWriter struct {
657		buf   bytes.Buffer
658		limit int
659		fail  error
660	}
661	
662	func (w *faultyWriter) Write(p []byte) (int, error) {
663		n := len(p)
664		if w.limit < n {
665			n = w.limit
666		}
667		w.buf.Write(p[:n])
668		if w.fail != nil {
669			return n, w.fail
670		}
671		return n, nil
672	}
673	
674	// blockingFeed is a reader whose data arrives incrementally; Read blocks
675	// while no chunk is available and returns EOF only after closeFeed.
676	type blockingFeed struct {
677		mu     sync.Mutex
678		cond   *sync.Cond
679		chunks [][]byte
680		closed bool
681	}
682	
683	func (b *blockingFeed) append(p []byte) {
684		b.mu.Lock()
685		b.chunks = append(b.chunks, append([]byte(nil), p...))
686		if b.cond != nil {
687			b.cond.Broadcast()
688		}
689		b.mu.Unlock()
690	}
691	
692	func (b *blockingFeed) closeFeed() {
693		b.mu.Lock()
694		b.closed = true
695		if b.cond != nil {
696			b.cond.Broadcast()
697		}
698		b.mu.Unlock()
699	}
700	
701	func (b *blockingFeed) Read(p []byte) (int, error) {
702		b.mu.Lock()
703		if b.cond == nil {
704			b.cond = sync.NewCond(&b.mu)
705		}
706		for len(b.chunks) == 0 && !b.closed {
707			b.cond.Wait()
708		}
709		if len(b.chunks) > 0 {
710			n := copy(p, b.chunks[0])
711			b.chunks = b.chunks[1:]
712			b.mu.Unlock()
713			return n, nil
714		}
715		b.mu.Unlock()
716		return 0, io.EOF
717	}
