func TestReliableDuplicateDataNeverDeliveredTwice(t *testing.T) {
	// Every DATA frame is duplicated by the network (as after a broad
	// ACK loss); the receiver still delivers each content once.
	const n = 20
	p := newReliablePair(t, n+2)
	defer p.close()
	stopPump := pumpAcks(t, p)
	defer stopPump()

	for i := 0; i < n; i++ {
		if err := p.a.WriteFrame(mkFrame(i)); err != nil {
			t.Fatal(err)
		}
	}
	if err := p.a.Flush(); err != nil {
		t.Fatal(err)
	}
	seen := map[uint64]bool{}
	p.dataToB(t, func(f Frame) bool {
		seq := f.Payload[0:8] // note: forwarding below does the duplication
		_ = seq
		return false
	})
	// Duplicate every forwarded frame into B's input as well.
	dup := bytes.NewBuffer(nil)
	orig := append([]byte(nil), p.aOut.Bytes()...)
	// aOut was consumed above; re-create the duplicated traffic: parse
	// orig and emit each frame twice.
	ps := NewSession(nil, bytes.NewReader(orig))
	for {
		f, err := ps.ReadFrame()
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			t.Fatal(err)
		}
		b, _ := Encode(f)
		dup.Write(b)
		dup.Write(b)
	}
	p.aOut.Reset()
	forward(t, dup, p.bIn, nil)

	for i := 0; i < n; i++ {
		f, err := p.b.ReadFrame()
		if err != nil {
			t.Fatalf("ReadFrame %d: %v", i, err)
		}
		want := mkFrame(i)
		if !framesEqual(f, want) {
			t.Fatalf("frame %d = %+v", i, f)
		}
		if seen[uint64(i)] {
			t.Fatalf("frame %d delivered twice", i)
		}
		seen[uint64(i)] = true
	}
	p.acksToA(t, nil)
	waitBase(t, p, n)
}

