// handleAck advances the cumulative send window and persists the new
// frontier. Stale ACKs (already covered) are harmless.
func (rs *ReliableSession) handleAck(ackSeq uint64) error {
	rs.wmu.Lock()
	defer rs.wmu.Unlock()

	if ackSeq < rs.base {
		return nil
	}
	newBase := ackSeq + 1
	if newBase > rs.nextSeq {
		newBase = rs.nextSeq
	}
	if newBase <= rs.base {
		return nil
	}
	for seq := rs.base; seq < newBase; seq++ {
		delete(rs.pending, seq)
	}
	rs.base = newBase
	return rs.persistLocked()
}

