func TestReliableSequenceSpaceWraparound(t *testing.T) {
	// Place the receiver right at the 2^64 boundary. Unsigned distance
	// arithmetic must accept the post-wrap seq 0..2 while rejecting a
	// genuine pre-wrap residue (MaxUint64-5) and an out-of-window
	// declared seq (3).
	const w = 3
	in := &blockingFeed{}
	r, err := NewReliableSession(NewSession(io.Discard, in), w, "", "")
	if err != nil {
		t.Fatal(err)
	}
	r.deliverNext = 0
	// Simulate "every seq below MaxUint64 already delivered": set the
	// frontier at the wrap point directly.
	r.rmu.Lock()
	r.deliverNext = ^uint64(0) - (w - 1) + 1 // = 2^64-2
	r.rmu.Unlock()

	feed := func(seq uint64) {
		b, _ := Encode(buildDataFrame(seq, reliableEntry{kind: uint8(seq), payload: []byte{byte(seq)}}))
		in.append(b)
	}
	// The boundary frame MaxUint64-2 delivers, advancing to MaxUint64-1.
	feed(^uint64(0) - 2)
	if _, err := r.ReadFrame(); err != nil {
		t.Fatalf("boundary frame: %v", err)
	}
	// Park the post-wrap frames out of order: MaxUint64, then 0 and 1
	// after MaxUint64-1 closes the gap.
	feed(^uint64(0))
	// It is now deliverNext+1 (distance 1), parked without error, but no
	// frame is deliverable yet. Do a blocking-free check by feeding the
	// missing MaxUint64-1 next.
	feed(^uint64(0) - 1)
	got1, err := r.ReadFrame()
	if err != nil {
		t.Fatalf("MaxUint64-1: %v", err)
	}
	if uint64(got1.Kind) != ^uint64(0)-1 {
		t.Fatalf("got kind %d", got1.Kind)
	}
	got2, err := r.ReadFrame() // releases parked MaxUint64
	if err != nil {
		t.Fatalf("MaxUint64: %v", err)
	}
	if uint64(got2.Kind) != ^uint64(0) {
		t.Fatalf("got kind %d, want MaxUint64", got2.Kind)
	}
	// deliverNext has wrapped to 0.
	r.rmu.Lock()
	dn := r.deliverNext
	r.rmu.Unlock()
	if dn != 0 {
		t.Fatalf("deliverNext = %d, want 0 after wrap", dn)
	}

	// A pre-wrap residue far behind the wrap is rejected.
	feed(^uint64(0) - 5)
	if _, err := r.ReadFrame(); !errors.Is(err, ErrChecksum) {
		t.Fatalf("pre-wrap residue err = %v, want ErrChecksum", err)
	}
}

